window.AUTH=window.AUTH||{};window.AUTH["23-867"]={"d":"23-867","id":"2024/23-867","n":"Republic of Hungary v. Simon","briefs":[{"k":"petitioner","label":"Brief of petitioner Republic of Hungary and Magyar Allamvasutak Zrt","date":"2024-08-26","url":"https://www.supremecourt.gov/DocketPDF/23/23-867/323352/20240826122931272_23-867%20Petitioners%20Opening%20Brief.pdf","side":"pet","n":103},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2024-09-03","url":"https://www.supremecourt.gov/DocketPDF/23/23-867/324002/20240903185425980_23-867tsacUnitedStates.pdf","side":"us","n":46},{"k":"respondent","label":"Brief of respondents Rosalie Simon, et al.","date":"2024-10-11","url":"https://www.supremecourt.gov/DocketPDF/23/23-867/328038/20241011121305459_Republic%20of%20Hungary%20v.%20Simon%20-%20Merits%20Response%20Brief%20FILE.pdf","side":"res","n":47},{"k":"reply","label":"Reply of petitioners Republic of Hungary, et al.","date":"2024-11-11","url":"https://www.supremecourt.gov/DocketPDF/23/23-867/331546/20241111090423271_23-867%20Petitioners%20Reply%20Brief.pdf","side":"pet","n":42}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/604us1r09_1b7d.pdf","tr":true,"items":[{"t":"case","label":"Abelesz v. Magyar Nemzeti Bank","cite":"692 F.3d 661","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/692/661/","ar":1,"by":{"0":"38"}},{"t":"case","label":"Agudas Chasidei Chabad of U.S. v. Russian Federation","cite":"466 F. Supp. 2d 6","y":2006,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/466/6/","by":{"0":"43"}},{"t":"case","label":"Allen v. Grand Cent. Aircraft Co.","cite":"347 U.S. 535","y":1954,"id":"scdb/1953-076","sc":1,"sum":"The pending administrative proceeding is valid, and the judgment of the District Court enjoining that proceeding is reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Alperin v. Vatican Bank","cite":"365 F. App’x 74","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/365/74/","by":{"0":"25"}},{"t":"case","label":"Ambar v. Federal Republic of Germany","cite":"596 F. Supp. 3d 76","y":2022,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/596/76/","by":{"0":"47"}},{"t":"case","label":"Apex Digit., Inc. v. Sears, Roebuck & Co.","cite":"572 F.3d 440","y":2009,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/572/440/","by":{"0":"12"}},{"t":"case","label":"Arbaugh v. Y&H Corp.","cite":"546 U.S. 500","y":2006,"id":"2005/04-944","sc":1,"sum":"The Court held that the number-of-employees requirement is an element of the merits of a Title VII claim, not a jurisdictional limitation.","sumSrc":"Oyez","by":{"0":"12"}},{"t":"case","label":"Architectural Ingenieria Siglo XXI, LLC v. Dominican Republic","cite":"788 F.3d 1329","y":2015,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/788/1329/","by":{"0":"47"}},{"t":"case","label":"Argentine Republic v. Amerada Hess Shipping Corp.","cite":"488 U.S. 428","y":1989,"id":"1988/87-1372","sc":1,"op":2,"sum":"The FSIA provides the sole basis for obtaining jurisdiction over a foreign state in United States courts, and the District Court correctly dismissed the action because the FSIA did not authorize jurisdiction over petitioner under the facts of this case.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6","1":"17"}},{"t":"case","label":"Asgrow Seed Co. v. Winterboer","cite":"513 U.S. 179","y":1995,"id":"1994/92-2038","sc":1,"sum":"The Court held that a farmer may sell for reproductive purposes only such seed as he has saved for the purpose of replanting his own fields. While the statute allows farmers to save seed to replant and then sell that saved seed to other farmers for planting, the statute prohibits growing protected seed as a \"step in marketing\" it as seed for planting.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Asociacion de Reclamantes v. United Mexican States","cite":"735 F.2d 1517","y":1984,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/735/1517/","by":{"0":"31"}},{"t":"case","label":"Banco Nacional de Cuba v. Sabbatino","cite":"376 U.S. 398","y":1964,"id":"1963/16","sc":1,"op":3,"sum":"The Supreme Court held that it will not decide the validity of a decree by a foreign government absent a treaty or other agreement. It did not matter that the taking violated customary international law. The majority noted that a judicial decision on this issue without a treaty would strain U.S.-Cuba relations.","sumSrc":"Oyez","by":{"0":"6, 17, 32","1":"9, 20, 21","2":"27, 28, 47","3":"1, 2, 17"}},{"t":"case","label":"Bolivarian Republic of Venezuela v. Helmerich & Payne Int’l Drilling Co.","cite":"581 U.S. 170","y":2017,"url":"https://supreme.justia.com/cases/federal/us/581/170/","sc":1,"op":5,"sum":"Observing that “this Court, like Congress, has paid special attention” to the Government's “views on sovereign immunity”.","sumSrc":"opinion","by":{"0":"42, 45, 46, 47, 48, 49","1":"7, 10, 17, 21, 26-29, 32","2":"32, 33, 34, 48, 49, 50","3":"2, 21, 22"}},{"t":"case","label":"Byrd v. Corporacion Forestal y Indus. de Olancho S.A.","cite":"182 F.3d 380","y":1999,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/182/380/","by":{"0":"39"}},{"t":"case","label":"Cargill Int’l S.A. v. M/T Pavel Dybenko","cite":"991 F.2d 1012","y":1993,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/991/1012/","by":{"0":"3, 39"}},{"t":"case","label":"Chase v. Wetzlar","cite":"225 U.S. 79","y":1912,"id":"scdb/1911-055","sc":1,"sum":"Where the jurisdiction of the Circuit Court is dependent, under § 8 of the act of 1875, upon property affected being within the jurisdiction, the defendants not being therein, the fact that the bill was dismissed because complainants failed-to prove the existence of any property within the jurisdiction does not affect the right of a direct appeal to this court under § 5 of the act of 1891.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"26","2":"41","3":"5"}},{"t":"case","label":"Comparelli v. Republica Bolivariana de Venezuela","cite":"891 F.3d 1311","y":2018,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/891/1311/","sum":"Holding Helmerich requires courts to determine “whether the nexus requirement is, in fact, established”.","sumSrc":"brief:0","by":{"0":"8, 46"}},{"t":"case","label":"DaimlerChrysler Corp. v. Cuno","cite":"547 U.S. 332","y":2006,"id":"2005/04-1704","sc":1,"sum":"The Supreme Court did not reach the central question presented, finding instead that Cuno and the other plaintiffs did not have standing to bring the suit. Chief Justice John Roberts, for the unanimous Court, wrote that simply alleging standing based on their status as taxpayers in Ohio and Michigan did not give them a sufficiently strong interest in the case.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"de Csepel v. Republic of Hungary","cite":"169 F. Supp. 3d 143","y":2016,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/169/143/","by":{"0":"22"}},{"t":"case","label":"de Csepel v. Republic of Hungary","cite":"859 F.3d 1094","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/859/1094/","by":{"0":"8"}},{"t":"case","label":"de Sanchez v. Banco Cent. de Nicaragua","cite":"770 F.2d 1385","y":1985,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/770/1385/","sum":"Explaining that the expropriation exception “parallels the so-called ‘Hickenlooper Exception’ to the act of state doctrine”.","sumSrc":"brief:0","by":{"0":"30"}},{"t":"case","label":"Dole Food Co. v. Patrickson","cite":"538 U.S. 468","y":2003,"id":"2002/01-593","sc":1,"sum":"The Court held, 7-2, that a foreign state must itself own a majority of the shares of a corporation if the corporation is to be deemed an instrumentality of the state under the provisions of the FSIA and, 9-0, that instrumentality status is determined at the time of the filing of the complaint.","sumSrc":"Oyez","by":{"0":"41, 48","1":"16"}},{"t":"case","label":"Fed. Ins. Co. v. Richard I. Rubin & Co.","cite":"12 F.3d 1270","y":1993,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/12/1270/","op":1,"by":{"0":"41"}},{"t":"case","label":"Federal Republic of Germany v. Philipp","cite":"141 S. Ct. 185","y":2020,"url":"https://www.courtlistener.com/c/S.%20Ct./141/185/","sc":1,"by":{"0":"10"}},{"t":"case","label":"Federal Republic of Germany v. Philipp","cite":"592 U.S. 169","y":2021,"id":"2020/19-351","sc":1,"op":9,"sum":"The Foreign Sovereign Immunities Act’s expropriation exception, 28 U. S. C. §1605(a)(3), incorporates the domestic takings rule, which recognizes that a foreign sovereign’s taking of its own nationals’ property is not a violation of international law.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"28, 29, 30, 32, 35, 36, 38, 41","1":"5, 20-22, 24, 29","2":"31, 37, 44, 45, 46, 51, 52"}},{"t":"case","label":"France.com, Inc. v. French Republic","cite":"992 F.3d 248","y":2021,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/992/248/","by":{"0":"8"}},{"t":"case","label":"Frank v. Gaos","cite":"586 U.S. 485","y":2019,"id":"2018/17-961","sc":1,"sum":"This class action settlement case is remanded for the courts below to address the plaintiffs’ standing in light of Spokeo, Inc. v. Robins, 578 U. S. ___.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"21, 44","3":"7"}},{"t":"case","label":"French v. Banco Nacional de Cuba","cite":"242 N.E.2d 704","y":1968,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/242/704/","op":2,"sum":"Observing that the amendment was “restricted, manifestly, to the kind of problem exemplifed by the Sabbatino case itself, a claim of title or other right to specifc property which had been expropriated abroad” (emphasis added).","sumSrc":"opinion","by":{"0":"32"}},{"t":"case","label":"Freund v. Republic of France","cite":"592 F. Supp. 2d 540","y":2008,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/592/540/","by":{"0":"25"}},{"t":"case","label":"Freund v. Société Nationale des Chemins de fer Français","cite":"391 F. App’x 939","y":2010,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/391/939/","by":{"0":"25"}},{"t":"case","label":"FTC v. Morton Salt Co.","cite":"334 U.S. 37","y":1948,"id":"scdb/1947-074","sc":1,"sum":"Respondent sells table salt in interstate commerce to wholesalers and retailers on a quantity discount basis. The Federal Trade Commission, after a hearing, found that respondent had discriminated in price between different purchasers of like grades and qualities, in violation of § 2 of the Clayton Act as amended by the Robinson-Patman Act, and issued a cease-and-desist order.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"Ghebreyesus v. Federal Democratic Republic of Ethiopia","cite":"2023 WL 6392611","y":2023,"court":"D. Nev. Sept. 30","by":{"0":"46"}},{"t":"case","label":"Goldman Sachs Grp., Inc. v. Ark. Tchr. Ret. Sys.","cite":"594 U.S. 113","y":2021,"url":"https://supreme.justia.com/cases/federal/us/594/113/","sc":1,"by":{"0":"44"}},{"t":"case","label":"Gross v. FBL Fin. Servs., Inc.","cite":"557 U.S. 167","y":2009,"id":"2008/08-441","sc":1,"sum":"The Court held that a plaintiff must show that age was the \"but-for\" cause for the defendant's action in an Age Discrimination in Employment Act claim.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Heller v. Republic of Hungary","cite":"2022 WL 2802351","y":2022,"court":"D.D.C. July 18","by":{"0":"14"}},{"t":"case","label":"Hertz Corp. v. Friend","cite":"559 U.S. 77","y":2010,"id":"2009/08-1107","sc":1,"sum":"The Court held that the court system cannot disregard the location of a corporation's principal place of business in a multi-state lawsuit.","sumSrc":"Oyez","by":{"0":"41","1":"31"}},{"t":"case","label":"Hunt v. Coastal States Gas Producing Co.","cite":"583 S.W.2d 322","y":1979,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.2d/583/322/","op":1,"by":{"0":"32"}},{"t":"case","label":"Int’l Ass’n of Machinists & Aerospace Workers (IAM) v. Org. of Petroleum Exporting Countries (OPEC)","cite":"649 F.2d 1354","y":1981,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/649/1354/","by":{"0":"30"}},{"t":"case","label":"Javierre v. Cent. Altagracia","cite":"217 U.S. 502","y":1910,"id":"scdb/1909-151","sc":1,"sum":"Where a proviso carves an exception, dependent on acondition, subsequent, out of the body of'a statute or contract, the party setting up the exception must prove, and has the burden,.that the condition subsequent has actually come to pass.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"K Mart Corp. v. Cartier, Inc.","cite":"486 U.S. 281","y":1988,"id":"1987/86-495","sc":1,"sum":"The judgment is affirmed in part and reversed in part. 252 U. S. App. D. C. 342, 790 F. 2d 903, affirmed in part and reversed in part. JUSTICE KENNEDY delivered the opinion of the Court as to Parts I, II-A, and II-C, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Keller v. Cent. Bank of Nigeria","cite":"277 F.3d 811","y":2002,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/277/811/","by":{"0":"39"}},{"t":"case","label":"Kiobel v. Royal Dutch Petroleum Co.","cite":"569 U.S. 108","y":2013,"id":"2011/10-1491","sc":1,"sum":"The Court found that the Alien Tort Statute does not give ground for United States law to be applied extraterrestrially to other sovereign nations with their own laws.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Kokkonen v. Guardian Life Ins. Co. of Am.","cite":"511 U.S. 375","y":1994,"id":"1993/93-263","sc":1,"sum":"A federal district court, possessing only that power authorized by Constitution and statute, lacks jurisdiction over a claim for breach of a contract, part of the consideration for which was dismissal of an earlier federal suit. No federal statute makes that connection (if it constitutionally could) the basis for federal-court jurisdiction over the contract dispute. Moreover, the doctrine of ancillary jurisdiction …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41","1":"31"}},{"t":"case","label":"Kumar v. Republic of Sudan","cite":"2019 WL 13251350","y":2019,"court":"E.D. Va. July 31","by":{"0":"46"}},{"t":"case","label":"McNutt v. Gen. Motors Acceptance Corp. of Indiana","cite":"298 U.S. 178","y":1936,"id":"scdb/1935-115","sc":1,"sum":"' Mr. Joseph W. Hutchinson, Assistant Attorney General of Indiana, and Mr. Leo M. Gardner, with whom Mr. Philip Lutz, Jr., Attorney General, was on the brief, for appellants.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"Medina v. California","cite":"505 U.S. 437","y":1992,"id":"1991/90-8370","sc":1,"sum":"Before petitioner Medina's trial for, inter alia, first-degree murder, the California court granted his motion for a competency hearing pursuant to a state law that forbids a mentally incompetent person to be tried or punished, establishes a presumption of competence, and placed on petitioner the burden of proving incompetence by a preponderance of the evidence. The jury empaneled for the competency hearing found …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Microsoft Corp. v. AT&T Corp.","cite":"550 U.S. 437","y":2007,"id":"2006/05-1056","sc":1,"sum":"The Court ruled 7-1 that Microsoft was not liable for infringement of AT&T's patent. The opinion by Justice Ruth Bader Ginsburg held that \"software code is an idea without physical embodiment\"; it cannot be a component of a patented invention.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Mitchell v. Forsyth","cite":"472 U.S. 511","y":1985,"id":"1984/84-335","sc":1,"sum":"In 1970, petitioner, who was then the Attorney General, authorized a warrantless wiretap for the purpose of gathering intelligence regarding the activities of a radical group that had made tentative plans to take actions threatening the Nation's security. During the time the wiretap was installed, the Government intercepted three conversations between a member of the group and respondent. Thereafter, this Court in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41, 48"}},{"t":"case","label":"N.L.R.B. v. Ky. River Cmty. Care, Inc.","cite":"532 U.S. 706","y":2001,"id":"2000/99-1815","sc":1,"sum":"The Court held that the burden of proving the applicability of the supervisory exception of the Act falls on the party asserting it. Justice Scalia wrote that the \"Act does not...expressly allocate the burden of proving or disproving a challenged employee's supervisory status.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Nat’l City Bank of N.Y. v. Republic of China","cite":"348 U.S. 356","y":1955,"id":"scdb/1954-035","sc":1,"op":1,"sum":"The counterclaims should not have been dismissed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 35","1":"18"}},{"t":"case","label":"Norton v. Larney","cite":"266 U.S. 511","y":1925,"id":"scdb/1924-067","sc":1,"sum":"1. An averment in a bill to quiet title to a Creek Indian allotment that the plaintiff went into possession by authority of treaties between the Creek Nation and the United States and the laws of Congress dealing with the lands and individuals of the Creek Nation, is insufficient to show that the case arose under those laws and treaties.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Oscar Mayer & Co. v. Evans","cite":"441 U.S. 750","y":1979,"id":"1978/78-275","sc":1,"sum":"Section 14 (b) of the Age Discrimination in Employment Act of 1967 (ADEA) provides that in the case of an alleged unlawful practice occurring in a State which has a law prohibiting discrimination in employment because of age and authorizing a state authority to grant and seek relief from such discriminatory practice, no suit may be brought under § 7 (c) of the ADEA before the expiration of 60 days after proceedings …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Owens v. Republic of Sudan","cite":"174 F. Supp. 3d 242","y":2016,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/174/242/","by":{"0":"43"}},{"t":"case","label":"Owens v. Republic of Sudan","cite":"864 F.3d 751","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/864/751/","by":{"0":"43"}},{"t":"case","label":"Pablo Star Ltd. v. Welsh Gov’t","cite":"961 F.3d 555","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/961/555/","by":{"0":"43","2":"37, 38"}},{"t":"case","label":"Permanent Mission of India to the United Nations v. City of New York","cite":"551 U.S. 193","y":2007,"id":"2006/06-134","sc":1,"sum":"The Court held 7-2 that the \"immovable property\" exception to sovereign immunity in the FSIA covers disputes over tax liens on the property as well as disputes over ownership and possession. The opinion by Justice Clarence Thomas ruled that a tax lien, by both its dictionary definition and its practical effect, is an interest or right in property.","sumSrc":"Oyez","by":{"0":"7","3":"19"}},{"t":"case","label":"Persinger v. Islamic Republic of Iran","cite":"729 F.2d 835","y":1984,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/729/835/","by":{"0":"35","1":"18"}},{"t":"case","label":"Phoenix Consulting, Inc. v. Republic of Angola","cite":"216 F.3d 36","y":2000,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/216/36/","by":{"0":"14"}},{"t":"case","label":"Precise Imports Corp. v. Kelly","cite":"378 F.2d 1014","y":1967,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/378/1014/","sum":"Holding “the plaintiff should bear the initial burden of producing evidence sufficient to justify a judgment in his favor”.","sumSrc":"brief:0","by":{"0":"42"}},{"t":"case","label":"Republic of Austria v. Altmann","cite":"541 U.S. 677","y":2004,"id":"2003/03-13","sc":1,"sum":"In a 6-to-3 decision written by Justice John Paul Stevens, the Court ruled that, while the Foreign Sovereign Immunities Act of 1976 does not explicitly state that it should be applied to actions that took place before its passage, there are strong indications in the text of the statute that Congress intended it to apply retroactively.","sumSrc":"Oyez","by":{"0":"5, 35","1":"29","2":"25, 26"}},{"t":"case","label":"Republic of Hungary v. Simon","cite":"141 S. Ct. 187","y":2020,"url":"https://www.courtlistener.com/c/S.%20Ct./141/187/","sc":1,"by":{"0":"10"}},{"t":"case","label":"Republic of Hungary v. Simon","cite":"592 U.S. 207","y":2021,"id":"2020/18-1447","sc":1,"op":9,"sum":"Judgment vacated and case remanded to the District of Columbia Circuit for further proceedings consistent with Federal Republic of Germany v. Philipp, 592 U. S. ___ (2021).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"10"}},{"t":"case","label":"Rosner v. United States","cite":"231 F. Supp. 2d 1202","y":2002,"court":"S.D. Fla.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/231/1202/","by":{"0":"23"}},{"t":"case","label":"Rosner v. United States","cite":"2005 WL 8155968","y":2005,"court":"S.D. Fla. Oct. 3","by":{"0":"23"}},{"t":"case","label":"Rukoro v. Federal Republic of Germany","cite":"976 F.3d 218","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/976/218/","by":{"0":"2, 24, 25, 46","1":"24","3":"22"}},{"t":"case","label":"Ryan v. Carter","cite":"93 U.S. 78","y":1876,"id":"scdb/1876-015","sc":1,"sum":"1. The first section of the act of June 13, 1812 (2 Stat; 748), mating further'provision for settling the claims to land in the Territory of Missouri, confirms, proprio vigore, the rights, titles, and claims to the lands embraced by it, and, to all intents and purposes, operates as agrant..","sumSrc":"Headnote (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Saudi Arabia v. Nelson","cite":"507 U.S. 349","y":1993,"id":"1992/91-522","sc":1,"op":1,"sum":"The Nelsons' action is not \"based upon a commercial activity\" within the meaning of the first clause of § 1605(a)(2), and the Act therefore confers no jurisdiction over their suit.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7","1":"31"}},{"t":"case","label":"Sheafen Kuo v. Gov’t of Taiwan","cite":"802 F. App’x 594","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/802/594/","by":{"0":"25"}},{"t":"case","label":"Simon v. E. Kentucky Welfare Rts. Org.","cite":"426 U.S. 26","y":1976,"id":"1975/74-1124","sc":1,"sum":"The District Court should have granted petitioners' motion to dismiss because respondents failed to establish their standing to bring this suit.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Simon v. Republic of Hungary","cite":"277 F. Supp. 3d 42","y":2017,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/277/42/","by":{"0":"10"}},{"t":"case","label":"Simon v. Republic of Hungary","cite":"37 F. Supp. 3d 381","y":2014,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/37/381/","by":{"0":"9, 37"}},{"t":"case","label":"Simon v. Republic of Hungary","cite":"443 F. Supp. 3d 88","y":2020,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/443/88/","by":{"0":"15, 22, 39","2":"33, 34, 35","3":"8, 9, 20"}},{"t":"case","label":"Simon v. Republic of Hungary","cite":"579 F. Supp. 3d 91","y":2021,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/579/91/","op":2,"by":{"0":"4, 13, 14, 37, 48"}},{"t":"case","label":"Simon v. Republic of Hungary","cite":"77 F.4th 1077","y":2023,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/77/1077/","op":4,"by":{"0":"28, 34, 39, 47, 48, 49, 50","3":"7, 18, 20, 22"}},{"t":"case","label":"Simon v. Republic of Hungary","cite":"812 F.3d 127","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/812/127/","op":2,"by":{"0":"13, 14, 22, 48","2":"8, 9, 30"}},{"t":"case","label":"Simon v. Republic of Hungary","cite":"911 F.3d 1172","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/911/1172/","op":1,"by":{"0":"10, 36","2":"8, 9, 30, 44"}},{"t":"case","label":"St. Mary’s Honor Ctr. v. Hicks","cite":"509 U.S. 502","y":1993,"id":"1992/92-602","sc":1,"sum":"The trier of fact's rejection of an employer's asserted reasons for its actions does not entitle a plaintiff to judgment as a matter of law.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43","2":"37, 51, 52"}},{"t":"case","label":"Texas Dep’t of Cmty. Affs. v. Burdine","cite":"450 U.S. 248","y":1981,"id":"1980/79-1764","sc":1,"sum":"A case that held that the defendant bears the burden of proof to provide nondiscriminatory reasons for termination after a former employee has proven a prima facie case that the termination violated the Title VII of the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"0":"42","3":"21"}},{"t":"case","label":"Transam. S.S. Corp. v. Somali Democratic Republic","cite":"767 F.2d 998","y":1985,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/767/998/","by":{"0":"15","1":"30, 31"}},{"t":"case","label":"Underhill v. Hernández","cite":"168 U.S. 250","y":1897,"id":"scdb/1897-017","sc":1,"sum":"Hernandez was in command of a revolutionary army in Venezuela when an engagement took place with the government forces which resulted in the defeat of the latter, and the occupation of Bolivar by the former. Underhill was living in Bolivar, where he had constructed a waterworks system for the' city under a contract with the government, and carried on a machinery repair business. He applied for a passport to leave …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"United States v. Lee","cite":"106 U.S. 196","y":1882,"id":"scdb/1882-052","sc":1,"by":{"0":"5"}},{"t":"case","label":"Verlinden B.V. v. Central Bank of Nigeria","cite":"461 U.S. 480","y":1983,"id":"1982/81-920","sc":1,"op":3,"ar":1,"sum":"The Supreme Court held that the FSIA does not violate Article III. The FSIA was a valid exercise of Congress’ power to regulate foreign commerce. On remand, the court of appeals should consider whether Central Bank is entitled to sovereign immunity.","sumSrc":"Oyez","by":{"0":"46, 47","1":"17-19, 32","3":"20"}},{"t":"case","label":"Zappia Middle E. Constr. Co. v. Emirate of Abu Dhabi","cite":"215 F.3d 247","y":2000,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/215/247/","by":{"0":"8"}},{"t":"usc","label":"22 U.S.C. § 2370","url":"https://www.law.cornell.edu/uscode/text/22/2370","subs":["(e)(2)"],"stext":{"head":"§2370. Prohibitions against furnishing assistance","paras":[[0,"(a) Cuba; embargo on all trade"],[0,"(1) No assistance shall be furnished under this chapter to the present government of Cuba. As an additional means of implementing and carrying into effect the policy of the preceding sentence, the President is authorized to establish and maintain a total embargo upon all trade between the United States and Cuba."],[0,"(2) Except as may be deemed necessary by the President in the interest of the United States, no assistance shall be furnished under this chapter to any government of Cuba, nor shall Cuba be entitled to receive any quota authorizing the importation of Cuban sugar into the United States or to receive any other benefit under any law of the United States, until the President determines that such government has taken appropriate steps according to international law standards to return to United States citizens, and to entities not less than 50 per centum beneficially owned by United States citizens, or to provide equitable compensation to such citizens and entities for property taken from such citizens and entities on or after January 1, 1959, by the Government of Cuba."],[0,"(b) Repealed. Pub. L. 97–113, title VII, §734(a)(1), Dec. 29, 1981, 95 Stat. 1560"],[0,"(c) Indebtedness of foreign country to United States citizen or person"],[0,"No assistance shall be provided under this chapter to the government of any country which is indebted to any United States citizen or person for goods or services furnished or ordered where (i) such citizen or person has exhausted available legal remedies, which shall include arbitration, or (ii) the debt is not denied or contested by such government, or (iii) such indebtedness arises under an unconditional guaranty of payment given by such government, or any predecessor government, directly or indirectly, through any controlled entity: Provided, That the President does not find such action contrary to the national security."],[0,"(d) Productive enterprises competing with United States enterprise; conditions on assistance; import controls; waiver of restriction by President"],[0,"No assistance shall be furnished on a loan basis under part I of subchapter I of this chapter for construction or operation of any productive enterprise in any country where such enterprise will compete with United States enterprise unless such country has agreed that it will establish appropriate procedures to prevent the exportation for use or consumption in the United States of more than twenty per centum of the annual production of such facility during the life of the loan. In case of failure to implement such agreement by the other contracting party, the President is authorized to establish necessary import controls to effectuate the agreement. The restrictions imposed by or pursuant to this subsection may be waived by the President where he determines that such waiver is in the national security interest."],[0,"(e) Nationalization, expropriation or seizure of property of United States citizens, or taxation or other exaction having same effect; failure to compensate or to provide relief from taxes, exactions, or conditions; report on full value of property by Foreign Claims Settlement Commission; act of state doctrine"],[0,"(1) The President shall suspend assistance to the government of any country to which assistance is provided under this chapter or any other Act when the government of such country or any government agency or subdivision within such country on or after January 1, 1962—"],[1,"(A) has nationalized or expropriated or seized ownership or control of property owned by any United States citizen or by any corporation, partnership, or association not less than 50 per centum beneficially owned by United States citizens, or"],[1,"(B) has taken steps to repudiate or nullify existing contracts or agreements with any United States citizen or any corporation, partnership, or association not less than 50 per centum beneficially owned by United States citizens, or"],[1,"(C) has imposed or enforced discriminatory taxes or other exactions, or restrictive maintenance or operational conditions, or has taken other actions, which have the effect of nationalizing, expropriating, or otherwise seizing ownership or control of property so owned,"],[0,"and such country, government agency, or government subdivision fails within a reasonable time (not more than six months after such action, or, in the event of a referral to the Foreign Claims Settlement Commission of the United States within such period as provided herein, not more than twenty days after the report of the Commission is received) to take appropriate steps, which may include arbitration, to discharge its obligations under international law toward such citizen or entity, including speedy compensation for such property in convertible foreign exchange, equivalent to the full value thereof, as required by international law, or fails to take steps designed to provide relief from such taxes, exactions, or conditions, as the case may be; and such suspension shall continue until the President is satisfied that appropriate steps are being taken, and provisions of this subsection shall not be waived with respect to any country unless the President determines and certifies that such a waiver is important to the national interests of the United States. Such certification shall be reported immediately to Congress."],[0,"Upon request of the President (within seventy days after such action referred to in subparagraphs (A), (B), or (C) of this paragraph, the Foreign Claims Settlement Commission of the United States (established pursuant to Reorganization Plan No. 1 of 1954, 68 Stat. 1279) is hereby authorized to evaluate expropriated property, determining the full value of any property nationalized, expropriated, or seized, or subjected to discriminatory or other actions as aforesaid, for purposes of this subsection and to render an advisory report to the President within ninety days after such request. Unless authorized by the President, the Commission shall not publish its advisory report except to the citizen or entity owning such property. There is hereby authorized to be appropriated such amount, to remain available until expended, as may be necessary from time to time to enable the Commission to carry out expeditiously its functions under this subsection."],[0,"(2) Notwithstanding any other provision of law, no court in the United States shall decline on the ground of the federal act of state doctrine to make a determination on the merits giving effect to the principles of international law in a case in which a claim of title or other rights to property is asserted by any party including a foreign state (or a party claiming through such state) based upon (or traced through) a confiscation or other taking after January 1, 1959, by an act of that state in violation of the principles of international law, including the principles of compensation and the other standards set out in this subsection: Provided, That this subparagraph shall not be applicable (1) in any case in which an act of a foreign state is not contrary to international law or with respect to a claim of title or other right to property acquired pursuant to an irrevocable letter of credit of not more than 180 days duration issued in good faith prior to the time of the confiscation or other taking, or (2) in any case with respect to which the President determines that application of the act of state doctrine is required in that particular case by the foreign policy interests of the United States and a suggestion to this effect is filed on his behalf in that case with the court."],[0,"(f) Prohibition against assistance to Communist countries; conditions for waiver of restriction by President; enumeration of Communist countries; removal from application of provisions; preconditions"],[0,"(1) No assistance shall be furnished under this chapter, (except section 2174(b) of this title) to any Communist country. This restriction may not be waived pursuant to any authority contained in this chapter unless the President finds and promptly reports to Congress that: (A) such assistance is vital to the security of the United States; (B) the recipient country is not controlled by the international Communist conspiracy; and (C) such assistance will further promote the independence of the recipient country from international communism. For the purposes of this subsection, the phrase \"Communist country\" includes specifically, but is not limited to, the following countries:"],[1,"Democratic People's Republic of Korea,"],[1,"People's Republic of China,"],[1,"Republic of Cuba,"],[1,"Socialist Republic of Vietnam,"],[1,"Tibet,1"],[0,"(2) Notwithstanding the provisions of paragraph (1) of this subsection, the President may remove a country, for such period as the President determines, from the application of this subsection, and other provisions which reference this subsection, if the President determines and reports to the Congress that such action is important to the national interest of the United States. It is the sense of the Congress that when consideration is given to authorizing assistance to a country removed from the application of this subsection, one of the factors to be weighed, among others, is whether the country in question is giving evidence of fostering the establishment of a genuinely democratic system, with respect for internationally recognized human rights."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/2370?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§2370. Prohibitions against furnishing assistance","tname":"Foreign Relations and Intercourse","by":{"0":"3, 6, 17, 30, 31, 32, 34","1":"21","2":"27, 28, 29, 48"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"4"}},{"t":"usc","label":"28 U.S.C. § 1330","url":"https://www.law.cornell.edu/uscode/text/28/1330","subs":["(a)"],"stext":{"head":"§1330. Actions against foreign states","paras":[[0,"(a) The district courts shall have original jurisdiction without regard to amount in controversy of any nonjury civil action against a foreign state as defined in section 1603(a) of this title as to any claim for relief in personam with respect to which the foreign state is not entitled to immunity either under sections 1605–1607 of this title or under any applicable international agreement."],[0,"(b) Personal jurisdiction over a foreign state shall exist as to every claim for relief over which the district courts have jurisdiction under subsection (a) where service has been made under section 1608 of this title."],[0,"(c) For purposes of subsection (b), an appearance by a foreign state does not confer personal jurisdiction with respect to any claim for relief not arising out of any transaction or occurrence enumerated in sections 1605–1607 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1330?type=usc&year=mostrecent&link-type=html"},"ar":2,"head":"§1330. Actions against foreign states","tname":"Judiciary and Judicial Procedure","by":{"0":"6, 45, 47","1":"1, 31","2":"40, 41, 43, 44, 45, 50, 51, 52","3":"23"}},{"t":"usc","label":"28 U.S.C. § 1602","url":"https://www.law.cornell.edu/uscode/text/28/1602","stext":{"head":"§1602. Findings and declaration of purpose","paras":[[0,"The Congress finds that the determination by United States courts of the claims of foreign states to immunity from the jurisdiction of such courts would serve the interests of justice and would protect the rights of both foreign states and litigants in United States courts. Under international law, states are not immune from the jurisdiction of foreign courts insofar as their commercial activities are concerned, and their commercial property may be levied upon for the satisfaction of judgments rendered against them in connection with their commercial activities. Claims of foreign states to immunity should henceforth be decided by courts of the United States and of the States in conformity with the principles set forth in this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1602?type=usc&year=mostrecent&link-type=html"},"head":"§1602. Findings and declaration of purpose","tname":"Judiciary and Judicial Procedure","by":{"0":"6, 45, 47","3":"23"}},{"t":"usc","label":"28 U.S.C. § 1603","url":"https://www.law.cornell.edu/uscode/text/28/1603","subs":["(a)"],"stext":{"head":"§1603. Definitions","paras":[[0,"For purposes of this chapter—"],[1,"(a) A \"foreign state\", except as used in section 1608 of this title, includes a political subdivision of a foreign state or an agency or instrumentality of a foreign state as defined in subsection (b)."],[1,"(b) An \"agency or instrumentality of a foreign state\" means any entity—"],[2,"(1) which is a separate legal person, corporate or otherwise, and"],[2,"(2) which is an organ of a foreign state or political subdivision thereof, or a majority of whose shares or other ownership interest is owned by a foreign state or political subdivision thereof, and"],[2,"(3) which is neither a citizen of a State of the United States as defined in section 1332 (c) and (e) of this title, nor created under the laws of any third country."],[1,"(c) The \"United States\" includes all territory and waters, continental or insular, subject to the jurisdiction of the United States."],[1,"(d) A \"commercial activity\" means either a regular course of commercial conduct or a particular commercial transaction or act. The commercial character of an activity shall be determined by reference to the nature of the course of conduct or particular transaction or act, rather than by reference to its purpose."],[1,"(e) A \"commercial activity carried on in the United States by a foreign state\" means commercial activity carried on by such state and having substantial contact with the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1603?type=usc&year=mostrecent&link-type=html"},"head":"§1603. Definitions","tname":"Judiciary and Judicial Procedure","by":{"0":"7","1":"3","2":"5"}},{"t":"usc","label":"28 U.S.C. § 1604","url":"https://www.law.cornell.edu/uscode/text/28/1604","stext":{"head":"§1604. Immunity of a foreign state from jurisdiction","paras":[[0,"Subject to existing international agreements to which the United States is a party at the time of enactment of this Act a foreign state shall be immune from the jurisdiction of the courts of the United States and of the States except as provided in sections 1605 to 1607 of this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1604?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1604. Immunity of a foreign state from jurisdiction","tname":"Judiciary and Judicial Procedure","by":{"0":"1, 7, 45","1":"3"}},{"t":"usc","label":"28 U.S.C. § 1605","url":"https://www.law.cornell.edu/uscode/text/28/1605","subs":["(a)","(a)(1)","(a)(2)","(a)(3)","(a)(4)","(a)(5)","(a)(6)"],"stext":{"head":"§1605. General exceptions to the jurisdictional immunity of a foreign state","paras":[[0,"(a) A foreign state shall not be immune from the jurisdiction of courts of the United States or of the States in any case—"],[1,"(1) in which the foreign state has waived its immunity either explicitly or by implication, notwithstanding any withdrawal of the waiver which the foreign state may purport to effect except in accordance with the terms of the waiver;"],[1,"(2) in which the action is based upon a commercial activity carried on in the United States by the foreign state; or upon an act performed in the United States in connection with a commercial activity of the foreign state elsewhere; or upon an act outside the territory of the United States in connection with a commercial activity of the foreign state elsewhere and that act causes a direct effect in the United States;"],[1,"(3) in which rights in property taken in violation of international law are in issue and that property or any property exchanged for such property is present in the United States in connection with a commercial activity carried on in the United States by the foreign state; or that property or any property exchanged for such property is owned or operated by an agency or instrumentality of the foreign state and that agency or instrumentality is engaged in a commercial activity in the United States;"],[1,"(4) in which rights in property in the United States acquired by succession or gift or rights in immovable property situated in the United States are in issue;"],[1,"(5) not otherwise encompassed in paragraph (2) above, in which money damages are sought against a foreign state for personal injury or death, or damage to or loss of property, occurring in the United States and caused by the tortious act or omission of that foreign state or of any official or employee of that foreign state while acting within the scope of his office or employment; except this paragraph shall not apply to—"],[2,"(A) any claim based upon the exercise or performance or the failure to exercise or perform a discretionary function regardless of whether the discretion be abused, or"],[2,"(B) any claim arising out of malicious prosecution, abuse of process, libel, slander, misrepresentation, deceit, or interference with contract rights; or"],[1,"(6) in which the action is brought, either to enforce an agreement made by the foreign state with or for the benefit of a private party to submit to arbitration all or any differences which have arisen or which may arise between the parties with respect to a defined legal relationship, whether contractual or not, concerning a subject matter capable of settlement by arbitration under the laws of the United States, or to confirm an award made pursuant to such an agreement to arbitrate, if (A) the arbitration takes place or is intended to take place in the United States, (B) the agreement or award is or may be governed by a treaty or other international agreement in force for the United States calling for the recognition and enforcement of arbitral awards, (C) the underlying claim, save for the agreement to arbitrate, could have been brought in a United States court under this section or section 1607, or (D) paragraph (1) of this subsection is otherwise applicable."],[0,"(b) A foreign state shall not be immune from the jurisdiction of the courts of the United States in any case in which a suit in admiralty is brought to enforce a maritime lien against a vessel or cargo of the foreign state, which maritime lien is based upon a commercial activity of the foreign state: Provided, That—"],[1,"(1) notice of the suit is given by delivery of a copy of the summons and of the complaint to the person, or his agent, having possession of the vessel or cargo against which the maritime lien is asserted; and if the vessel or cargo is arrested pursuant to process obtained on behalf of the party bringing the suit, the service of process of arrest shall be deemed to constitute valid delivery of such notice, but the party bringing the suit shall be liable for any damages sustained by the foreign state as a result of the arrest if the party bringing the suit had actual or constructive knowledge that the vessel or cargo of a foreign state was involved; and"],[1,"(2) notice to the foreign state of the commencement of suit as provided in section 1608 of this title is initiated within ten days either of the delivery of notice as provided in paragraph (1) of this subsection or, in the case of a party who was unaware that the vessel or cargo of a foreign state was involved, of the date such party determined the existence of the foreign state's interest."],[0,"(c) Whenever notice is delivered under subsection (b)(1), the suit to enforce a maritime lien shall thereafter proceed and shall be heard and determined according to the principles of law and rules of practice of suits in rem whenever it appears that, had the vessel been privately owned and possessed, a suit in rem might have been maintained. A decree against the foreign state may include costs of the suit and, if the decree is for a money judgment, interest as ordered by the court, except that the court may not award judgment against the foreign state in an amount greater than the value of the vessel or cargo upon which the maritime lien arose. Such value shall be determined as of the time notice is served under subsection (b)(1). Decrees shall be subject to appeal and revision as provided in other cases of admiralty and maritime jurisdiction. Nothing shall preclude the plaintiff in any proper case from seeking relief in personam in the same action brought to enforce a maritime lien as provided in this section."],[0,"(d) A foreign state shall not be immune from the jurisdiction of the courts of the United States in any action brought to foreclose a preferred mortgage, as defined in section 31301 of title 46. Such action shall be brought, heard, and determined in accordance with the provisions of chapter 313 of title 46 and in accordance with the principles of law and rules of practice of suits in rem, whenever it appears that had the vessel been privately owned and possessed a suit in rem might have been maintained."],[0,"[(e), (f) Repealed. Pub. L. 110–181, div. A, title X, §1083(b)(1)(B), Jan. 28, 2008, 122 Stat. 341.]"],[0,"(g) Limitation on Discovery.—"],[1,"(1) In general.—(A) Subject to paragraph (2), if an action is filed that would otherwise be barred by section 1604, but for section 1605A or section 1605B, the court, upon request of the Attorney General, shall stay any request, demand, or order for discovery on the United States that the Attorney General certifies would significantly interfere with a criminal investigation or prosecution, or a national security operation, related to the incident that gave rise to the cause of action, until such time as the Attorney General advises the court that such request, demand, or order will no longer so interfere."],[1,"(B) A stay under this paragraph shall be in effect during the 12-month period beginning on the date on which the court issues the order to stay discovery. The court shall renew the order to stay discovery for additional 12-month periods upon motion by the United States if the Attorney General certifies that discovery would significantly interfere with a criminal investigation or prosecution, or a national security operation, related to the incident that gave rise to the cause of action."],[1,"(2) Sunset.—(A) Subject to subparagraph (B), no stay shall be granted or continued in effect under paragraph (1) after the date that is 10 years after the date on which the incident that gave rise to the cause of action occurred."],[1,"(B) After the period referred to in subparagraph (A), the court, upon request of the Attorney General, may stay any request, demand, or order for discovery on the United States that the court finds a substantial likelihood would—"],[2,"(i) create a serious threat of death or serious bodily injury to any person;"],[2,"(ii) adversely affect the ability of the United States to work in cooperation with foreign and international law enforcement agencies in investigating violations of United States law; or"],[2,"(iii) obstruct the criminal case related to the incident that gave rise to the cause of action or undermine the potential for a conviction in such case."],[1,"(3) Evaluation of evidence.—The court's evaluation of any request for a stay under this subsection filed by the Attorney General shall be conducted ex parte and in camera."],[1,"(4) Bar on motions to dismiss.—A stay of discovery under this subsection shall constitute a bar to the granting of a motion to dismiss under rules 12(b)(6) and 56 of the Federal Rules of Civil Procedure."],[1,"(5) Construction.—Nothing in this subsection shall prevent the United States from seeking protective orders or asserting privileges ordinarily available to the United States."],[0,"(h) Jurisdictional Immunity for Certain Art Exhibition Activities.—"],[1,"(1) In general.—If—"],[2,"(A) a work is imported into the United States from any foreign state pursuant to an agreement that provides for the temporary exhibition or display of such work entered into between a foreign state that is the owner or custodian of such work and the United States or one or more cultural or educational institutions within the United States;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1605?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1605. General exceptions to the jurisdictional immunity of a foreign state","tname":"Judiciary and Judicial Procedure","by":{"0":"5, 7, 7, 19, 20, 25, 31, 32, 43, 7, 7, 17, 28, 29, 7","1":"3, 3-5, 8, 11-16, 21-23, 29","2":"39, 40, 42, 43, 44, 45, 49, 45, 46","3":"1, 12"}},{"t":"usc","label":"28 U.S.C. § 1605A","url":"https://www.law.cornell.edu/uscode/text/28/1605A","subs":["(a)(1)","(a)(2)(A)","(a)(2)(A)(i)","(a)(2)(A)(ii)","(a)","(h)"],"stext":{"head":"§1605A. Terrorism exception to the jurisdictional immunity of a foreign state","paras":[[0,"(a) In General.—"],[1,"(1) No immunity.—A foreign state shall not be immune from the jurisdiction of courts of the United States or of the States in any case not otherwise covered by this chapter in which money damages are sought against a foreign state for personal injury or death that was caused by an act of torture, extrajudicial killing, aircraft sabotage, hostage taking, or the provision of material support or resources for such an act if such act or provision of material support or resources is engaged in by an official, employee, or agent of such foreign state while acting within the scope of his or her office, employment, or agency."],[1,"(2) Claim heard.—The court shall hear a claim under this section if—"],[2,"(A)(i)(I) the foreign state was designated as a state sponsor of terrorism at the time the act described in paragraph (1) occurred, or was so designated as a result of such act, and, subject to subclause (II), either remains so designated when the claim is filed under this section or was so designated within the 6-month period before the claim is filed under this section; or"],[2,"(II) in the case of an action that is refiled under this section by reason of section 1083(c)(2)(A) of the National Defense Authorization Act for Fiscal Year 2008 or is filed under this section by reason of section 1083(c)(3) of that Act, the foreign state was designated as a state sponsor of terrorism when the original action or the related action under section 1605(a)(7) (as in effect before the enactment of this section) or section 589 of the Foreign Operations, Export Financing, and Related Programs Appropriations Act, 1997 (as contained in section 101(c) of division A of Public Law 104–208) was filed;"],[2,"(ii) the claimant or the victim was, at the time the act described in paragraph (1) occurred—"],[3,"(I) a national of the United States;"],[3,"(II) a member of the armed forces; or"],[3,"(III) otherwise an employee of the Government of the United States, or of an individual performing a contract awarded by the United States Government, acting within the scope of the employee's employment; and"],[2,"(iii) in a case in which the act occurred in the foreign state against which the claim has been brought, the claimant has afforded the foreign state a reasonable opportunity to arbitrate the claim in accordance with the accepted international rules of arbitration; or"],[2,"(B) the act described in paragraph (1) is related to Case Number 1:00CV03110 (EGS) in the United States District Court for the District of Columbia."],[0,"(b) Limitations.—An action may be brought or maintained under this section if the action is commenced, or a related action was commenced under section 1605(a)(7) (before the date of the enactment of this section) or section 589 of the Foreign Operations, Export Financing, and Related Programs Appropriations Act, 1997 (as contained in section 101(c) of division A of Public Law 104–208) not later than the latter of—"],[1,"(1) 10 years after April 24, 1996; or"],[1,"(2) 10 years after the date on which the cause of action arose."],[0,"(c) Private Right of Action.—A foreign state that is or was a state sponsor of terrorism as described in subsection (a)(2)(A)(i), and any official, employee, or agent of that foreign state while acting within the scope of his or her office, employment, or agency, shall be liable to—"],[1,"(1) a national of the United States,"],[1,"(2) a member of the armed forces,"],[1,"(3) an employee of the Government of the United States, or of an individual performing a contract awarded by the United States Government, acting within the scope of the employee's employment, or"],[1,"(4) the legal representative of a person described in paragraph (1), (2), or (3),"],[0,"for personal injury or death caused by acts described in subsection (a)(1) of that foreign state, or of an official, employee, or agent of that foreign state, for which the courts of the United States may maintain jurisdiction under this section for money damages. In any such action, damages may include economic damages, solatium, pain and suffering, and punitive damages. In any such action, a foreign state shall be vicariously liable for the acts of its officials, employees, or agents."],[0,"(d) Additional Damages.—After an action has been brought under subsection (c), actions may also be brought for reasonably foreseeable property loss, whether insured or uninsured, third party liability, and loss claims under life and property insurance policies, by reason of the same acts on which the action under subsection (c) is based."],[0,"(e) Special Masters.—"],[1,"(1) In general.—The courts of the United States may appoint special masters to hear damage claims brought under this section."],[1,"(2) Transfer of funds.—The Attorney General shall transfer, from funds available for the program under section 1404C of the Victims of Crime Act of 1984 (42 U.S.C. 10603c),1 to the Administrator of the United States district court in which any case is pending which has been brought or maintained under this section such funds as may be required to cover the costs of special masters appointed under paragraph (1). Any amount paid in compensation to any such special master shall constitute an item of court costs."],[0,"(f) Appeal.—In an action brought under this section, appeals from orders not conclusively ending the litigation may only be taken pursuant to section 1292(b) of this title."],[0,"(g) Property Disposition.—"],[1,"(1) In general.—In every action filed in a United States district court in which jurisdiction is alleged under this section, the filing of a notice of pending action pursuant to this section, to which is attached a copy of the complaint filed in the action, shall have the effect of establishing a lien of lis pendens upon any real property or tangible personal property that is—"],[2,"(A) subject to attachment in aid of execution, or execution, under section 1610;"],[2,"(B) located within that judicial district; and"],[2,"(C) titled in the name of any defendant, or titled in the name of any entity controlled by any defendant if such notice contains a statement listing such controlled entity."],[1,"(2) Notice.—A notice of pending action pursuant to this section shall be filed by the clerk of the district court in the same manner as any pending action and shall be indexed by listing as defendants all named defendants and all entities listed as controlled by any defendant."],[1,"(3) Enforceability.—Liens established by reason of this subsection shall be enforceable as provided in chapter 111 of this title."],[0,"(h) Definitions.—For purposes of this section—"],[1,"(1) the term \"aircraft sabotage\" has the meaning given that term in Article 1 of the Convention for the Suppression of Unlawful Acts Against the Safety of Civil Aviation;"],[1,"(2) the term \"hostage taking\" has the meaning given that term in Article 1 of the International Convention Against the Taking of Hostages;"],[1,"(3) the term \"material support or resources\" has the meaning given that term in section 2339A of title 18;"],[1,"(4) the term \"armed forces\" has the meaning given that term in section 101 of title 10;"],[1,"(5) the term \"national of the United States\" has the meaning given that term in section 101(a)(22) of the Immigration and Nationality Act (8 U.S.C. 1101(a)(22));"],[1,"(6) the term \"state sponsor of terrorism\" means a country the government of which the Secretary of State has determined, for purposes of section 6(j) of the Export Administration Act of 1979 (50 U.S.C. App. 2405(j)),1 section 620A of the Foreign Assistance Act of 1961 (22 U.S.C. 2371), section 40 of the Arms Export Control Act (22 U.S.C. 2780), or any other provision of law, is a government that has repeatedly provided support for acts of international terrorism; and"],[1,"(7) the terms \"torture\" and \"extrajudicial killing\" have the meaning given those terms in section 3 of the Torture Victim Protection Act of 1991 (28 U.S.C. 1350 note)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1605A?type=usc&year=mostrecent&link-type=html"},"head":"§1605A. Terrorism exception to the jurisdictional immunity of a foreign state","tname":"Judiciary and Judicial Procedure","by":{"0":"7, 29, 29, 17, 29, 29","2":"46, 46"}},{"t":"usc","label":"28 U.S.C. § 1655","url":"https://www.law.cornell.edu/uscode/text/28/1655","by":{"0":"26"}},{"t":"rule","label":"Fed. R. Civ. P. 12","url":"https://www.law.cornell.edu/rules/frcp/rule_12","subs":["(b)(1)","(b)(6)"],"by":{"0":"12","2":"33, 33"}},{"t":"case","label":"Abramski v. United States","cite":"573 U.S. 169","y":2014,"id":"2013/12-1493","sc":1,"ar":1,"sum":"The Court held that a firearm purchaser's intent to sell their gun to another buyer is necessary information for the seller's records.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Alfred Dunhill of London, Inc. v. Republic of Cuba","cite":"425 U.S. 682","y":1976,"id":"1974/73-1288","sc":1,"sum":"The Supreme Court held that the record contained no evidence to support an act of state. There was no statute, decree or order by the Cuban Government refusing to pay, only a statement by the interventor’s counsel during trial. The interventors did not possess governmental power just because the Cuban government appointed them. The affirmative judgment for the one purchaser was restored.","sumSrc":"Oyez","by":{"1":"18, 19","2":"31"}},{"t":"case","label":"American Insurance Association v. Garamendi","cite":"539 U.S. 396","y":2003,"id":"2002/02-722","sc":1,"sum":"The Court held that California's HVIRA interferes with the president's ability to conduct the nation's foreign policy and is therefore preempted. The Court reasoned that an exercise of state power that concerns foreign relations must yield to the Federal Government's policy or that generally there is executive authority to decide what policy should be implemented.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"(III) Cases—Continued: Ashcroft v. Iqbal","cite":"556 U.S. 662","y":2009,"id":"2008/07-1015","sc":1,"sum":"The Court found that high-ranking government officials were not liable for unconstitutional acts by subordinate officials.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Azar v. Allina Health Services","cite":"587 U.S. 566","y":2019,"id":"2018/17-1484","sc":1,"sum":"Because the Department of Health and Human Services neglected its statutory notice-and-comment obligations when it revealed a new policy that dramatically—and retroactively—reduced Medicare payments to hospitals serving low-income patients, its policy must be vacated.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"31"}},{"t":"case","label":"Badgerow v. Walters","cite":"596 U.S. 1","y":2022,"id":"2021/20-1143","sc":1,"sum":"Federal jurisdiction in a petition to compel arbitration under Section 4 of the Federal Arbitration Act is determined by “looking through” the petition to the jurisdictional basis of the “underlying substantive controversy,” Vaden v. Discover Bank, 556 U. S. 49, 62, but that approach does not apply to petitions to confirm or vacate arbitral awards under Sections 9 and 10 of the FAA.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"22"}},{"t":"case","label":"Baker Botts L.L.P. v. ASARCO LLC","cite":"576 U.S. 121","y":2015,"id":"2014/14-103","sc":1,"sum":"The Court held that the Bankruptcy Code does not provide an explicit statutory exception to the American rule of attorney fees—that each litigant pays for his own attorney’s fees.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"Belize Social Development Ltd. v. Government of Belize","cite":"794 F.3d 99","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/794/99/","by":{"1":"30"}},{"t":"case","label":"Bell Atlantic Corp. v. Twombly","cite":"550 U.S. 544","y":2007,"id":"2006/05-1126","sc":1,"sum":"The Court ruled 7-2 that a plaintiff claiming a Section 1 violation must also allege facts that, if true, would suggest a conspiratorial agreement.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Boos v. Barry","cite":"485 U.S. 312","y":1988,"id":"1987/86-803","sc":1,"sum":"The Court found that the Code's restriction on sign displays violated the First Amendment while the ban on congregations did not. First, Justice O'Connor argued that the prohibition on signs failed to meet the high standards that the Court uses when evaluating the content-based regulation of political speech in a public forum.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"FBI v. Fikre","cite":"601 U.S. 234","y":2024,"id":"2023/22-1178","sc":1,"sum":"The Government failed to meet its burden to demonstrate that Mr. Fikre’s removal from the Government’s No Fly List mooted his 42 U. S. C. §1983 case because its declaration did not disclose the conduct that landed Mr. Fikre on the No Fly List and did not ensure that he would not be placed back on the list for engaging in the same or similar conduct in the future.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"28"}},{"t":"case","label":"Great-West Life & Annuity Insurance Co. v. Knudson","cite":"534 U.S. 204","y":2002,"id":"2001/99-1786","sc":1,"sum":"The Court held that because Great-West is seeking legal relief - the imposition of personal liability on Knudson for a contractual obligation to pay money - ERISA does not authorize this action.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Gwaltney of Smithfield, Ltd. v. Chesapeake Bay Foundation, Inc.","cite":"484 U.S. 49","y":1987,"id":"1987/86-473","sc":1,"sum":"Section 505(a) of the Clean Water Act authorizes private citizens to commence a civil action for injunctive relief and/or the imposition of civil penalties in federal district court against any person \"alleged to be in violation\" of the conditions of a National Pollutant Discharge Elimination System (NPDES) permit. Between 1981 and 1984, petitioner repeatedly violated the conditions of its NPDES permit by exceeding …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28"}},{"t":"case","label":"Helvering v. William Flaccus Oak Leather Co.","cite":"313 U.S. 247","y":1941,"id":"scdb/1940-124","sc":1,"sum":"A sum received by a taxpayer as proceeds of insurance on buildings and equipment destroyed by fire (no part of the sum so received having been expended to replace the destroyed property, which prior to 1935 had been completely depreciated for income tax purposes), held not a gain from the \"sale or exchange\" of capital assets within the meaning of § 117 (d) of the Revenue Act of 1934. P. 249. 114 F. 2d 783, reversed. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13"}},{"t":"case","label":"Johnson v. City of Shelby","cite":"574 U.S. 10","y":2014,"id":"2014/13-1318","sc":1,"sum":"The Court held that federal pleading rules require only a “short plain statement of the claim showing that the pleader is entitled to relief,” not a complete statement of the legal theory supporting the claim.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Luis v. United States","cite":"578 U.S. 5","y":2016,"id":"2015/14-419","sc":1,"op":1,"sum":"The Court determined that the pretrial restraining of a defendant's assets untainted by their crime that are needed to retain counsel of choice violates the Sixth Amendment.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"National Rifle Association v. Vullo","cite":"602 U.S. 175","y":2024,"id":"2023/22-842","sc":1,"sum":"The NRA plausibly alleged that respondent violated the First Amendment by coercing regulated entities to terminate their business relationships with the NRA in order to punish or suppress the NRA’s gun-promotion advocacy.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"28"}},{"t":"case","label":"Preston v. Keene","cite":"39 U.S. 133","y":1840,"id":"scdb/1840-018","sc":1,"sum":"Louisiana. A paper was executed by R. R. K., of the city of New Orleans, stating that the grantor, for, and in consideration of, a certain lot or parcel of land, (describing it,) conveyed and transferred to J. B. and S. B. all his right, title, and interest in a certain tract or parcel of land, (describing it,) hereby warranting and defending unto the said J. 3. and S. B. all his right and title in the same, and …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"12"}},{"t":"case","label":"Republic of Sudan v. Harrison","cite":"587 U.S. 1","y":2019,"id":"2018/16-1094","sc":1,"sum":"When civil process is served on a foreign state under the Foreign Sovereign Immunities Act of 1976, 28 U. S. C. §1608(a)(3) requires a mailing to be sent directly to the foreign minister’s office in the foreign state.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"12"}},{"t":"case","label":"Sandifer v. United States Steel Corp.","cite":"571 U.S. 220","y":2014,"id":"2013/12-417","sc":1,"sum":"The Court held that putting on safety garments constitutes \"changing clothes\" under the Fair Labor Standards Act.","sumSrc":"Oyez","by":{"1":"12"}},{"t":"case","label":"Truck Insurance Exchange v. Kaiser Gypsum Co.","cite":"144 S. Ct. 1414","y":2024,"id":"2023/22-1079","sc":1,"op":1,"sum":"An insurer with financial responsibility for bankruptcy claims is a “party in interest” under 11 U. S. C. §1109(b) that “may raise and may appear and be heard on any issue” in a Chapter 11 case.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"23"}},{"t":"case","label":"Victory Transport Inc. v. Comisaria General de Abastecimientos y Transportes","cite":"336 F.2d 354","y":1964,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/336/354/","sum":"Explaining that under the restrictive theory, “legislative acts, such as nationalization,” are public acts.","sumSrc":"brief:1","by":{"1":"20"}},{"t":"usc","label":"28 U.S.C. § 1606","url":"https://www.law.cornell.edu/uscode/text/28/1606","by":{"1":"3"}},{"t":"usc","label":"28 U.S.C. § 1391","url":"https://www.law.cornell.edu/uscode/text/28/1391","by":{"1":"33"}},{"t":"case","label":"Agudas Chasidei Chabad of United States v. Russian Federation","cite":"528 F.3d 934","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/528/934/","by":{"2":"30, 31"}},{"t":"case","label":"Aldossari ex rel. Aldossari v. Ripp","cite":"49 F.4th 236","y":2022,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/49/236/","by":{"2":"38"}},{"t":"case","label":"County of Maui v. Hawaii Wildlife Fund","cite":"590 U.S. 165","y":2020,"id":"2019/18-260","sc":1,"sum":"The Court held the Clean Water Act requires a permit when pollutants originate from a point source but are conveyed to navigable waters by a nonpoint source, such as groundwater, if the conveyance is the \"functional equivalent\" of a direct discharge.","sumSrc":"Oyez","by":{"2":"25, 44"}},{"t":"case","label":"Enahoro v. Abubakar","cite":"408 F.3d 877","y":2005,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/408/877/","by":{"2":"38"}},{"t":"case","label":"Florida Department of State v. Treasure Salvors, Inc.","cite":"458 U.S. 670","y":1982,"id":"1981/80-1348","sc":1,"sum":"The Court first held that while a state enjoys limited immunity from federal process under the Eleventh Amendment, its officers do not. In the present case, the seizure warrant was filed against Florida's officers in the Archives.","sumSrc":"Oyez","by":{"2":"23, 43"}},{"t":"case","label":"Frank v. Commonwealth of Antigua & Barbuda","cite":"842 F.3d 362","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/842/362/","by":{"2":"38"}},{"t":"case","label":"Friedman v. Republic of Hungary","cite":"144 S. Ct. 2686","y":2024,"url":"https://www.courtlistener.com/c/S.%20Ct./144/2686/","sc":1,"by":{"2":"49"}},{"t":"case","label":"GDG Acquisitions LLC v. Government of Belize","cite":"849 F.3d 1299","y":2017,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/849/1299/","by":{"2":"38"}},{"t":"case","label":"Gerding v. Republic of France","cite":"943 F.2d 521","y":1991,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/943/521/","by":{"2":"38"}},{"t":"case","label":"Goldman Sachs Group, Inc. v. Arkansas Teacher Retirement System","cite":"594 U.S. 113","y":2021,"id":"2020/20-222","sc":1,"sum":"The generic nature of a misrepresentation in connection with the sale of securities often is important evidence of price impact that courts should consider at class certification; defendants bear the burden of persuasion to prove a lack of price impact by a preponderance of the evidence at class certification.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"51"}},{"t":"case","label":"Hansen v. PT Bank Negara Indonesia (Persero), TBK","cite":"601 F.3d 1059","y":2010,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/601/1059/","by":{"2":"38"}},{"t":"case","label":"Madewell v. Downs","cite":"68 F.3d 1030","y":1995,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/68/1030/","by":{"2":"22"}},{"t":"case","label":"Marine Bank v. Fulton Bank","cite":"69 U.S. 252","y":1865,"id":"scdb/1864-012","sc":1,"sum":"1. Money collected by one-bank for another, placed by the collecting bank with the bulk of its ordinary banking funds, and credited to the transmitting bank' in account, becomes the money of the former. Hence, any depreciation in the specific bank bills received by the collecting bank, which may happen between the date of the collecting banks’ receiving them and the other banks’ drawing for the amount collected, …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"19"}},{"t":"case","label":"O’Bryan v. Holy See","cite":"556 F.3d 361","y":2009,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/556/361/","by":{"2":"38"}},{"t":"case","label":"Patel v. Garland","cite":"596 U.S. 328","y":2022,"id":"2021/20-979","sc":1,"sum":"Federal courts lack jurisdiction to review facts found as part of any judgment relating to the granting of discretionary-relief in immigration proceedings enumerated under 8 U. S. C. §1252(a)(2)(B)(i).","sumSrc":"Holding (supremecourt.gov)","by":{"2":"20, 21, 24"}},{"t":"case","label":"Pennsylvania v. Dunlap","cite":"555 U.S. 964","y":2008,"url":"https://supreme.justia.com/cases/federal/us/555/964/","sc":1,"by":{"2":"21"}},{"t":"case","label":"Robers v. United States","cite":"572 U.S. 639","y":2014,"id":"2013/12-9012","sc":1,"sum":"The Court held that, under the Mandatory Victims Restitution Act, individuals accused of property crime must pay “an amount equal to...the value of the property,” minus “the value...of any part of the property that is returned\" in retribution.","sumSrc":"Oyez","by":{"2":"23, 41, 43"}},{"t":"case","label":"United States v. $46,588.00 in U.S. Currency & $20.00 in Canadian Currency","cite":"103 F.3d 902","y":1996,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/103/902/","by":{"2":"22, 36","3":"12"}},{"t":"case","label":"United States v. $57,480.05 U.S. Currency & Other Coins","cite":"722 F.2d 1457","y":1984,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/722/1457/","by":{"2":"22"}},{"t":"case","label":"United States v. Moore","cite":"27 F.3d 969","y":1994,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/27/969/","by":{"2":"36","3":"13"}},{"t":"case","label":"United States v. Pangang Group Co.","cite":"6 F.4th 946","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/6/946/","by":{"2":"38"}},{"t":"case","label":"Universal Trading & Investment Co. v. Bureau for Representing Ukrainian Interests in International & Foreign Courts","cite":"727 F.3d 10","y":2013,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/727/10/","by":{"2":"38"}},{"t":"case","label":"Wisconsin Central Ltd. v. United States","cite":"585 U.S. 274","y":2018,"id":"2017/17-530","sc":1,"sum":"The Court decided that employee stock options are not taxable “compensation” under the Railroad Retirement Tax Act because they are not “money remuneration.”","sumSrc":"Oyez","by":{"2":"21, 46"}},{"t":"const","label":"Amendment XI","clauses":[["eleventh-amendment","Eleventh Amendment"]],"text":"The Judicial power of the United States shall not be construed to extend to any suit in law or equity, commenced or prosecuted against one of the United States by Citizens of another State, or by Citizens or Subjects of any Foreign State.","by":{"2":"22, 23"}},{"t":"usc","label":"18 U.S.C. § 1957","url":"https://www.law.cornell.edu/uscode/text/18/1957","subs":["(a)","(f)(2)"],"stext":{"head":"§1957. Engaging in monetary transactions in property derived from specified unlawful activity","paras":[[0,"(a) Whoever, in any of the circumstances set forth in subsection (d), knowingly engages or attempts to engage in a monetary transaction in criminally derived property of a value greater than $10,000 and is derived from specified unlawful activity, shall be punished as provided in subsection (b)."],[0,"(b)(1) Except as provided in paragraph (2), the punishment for an offense under this section is a fine under title 18, United States Code, or imprisonment for not more than ten years or both. If the offense involves a pre-retail medical product (as defined in section 670) the punishment for the offense shall be the same as the punishment for an offense under section 670 unless the punishment under this subsection is greater."],[0,"(2) The court may impose an alternate fine to that imposable under paragraph (1) of not more than twice the amount of the criminally derived property involved in the transaction."],[0,"(c) In a prosecution for an offense under this section, the Government is not required to prove the defendant knew that the offense from which the criminally derived property was derived was specified unlawful activity."],[0,"(d) The circumstances referred to in subsection (a) are—"],[1,"(1) that the offense under this section takes place in the United States or in the special maritime and territorial jurisdiction of the United States; or"],[1,"(2) that the offense under this section takes place outside the United States and such special jurisdiction, but the defendant is a United States person (as defined in section 3077 of this title, but excluding the class described in paragraph (2)(D) of such section)."],[0,"(e) Violations of this section may be investigated by such components of the Department of Justice as the Attorney General may direct, and by such components of the Department of the Treasury as the Secretary of the Treasury may direct, as appropriate, and, with respect to offenses over which the Department of Homeland Security has jurisdiction, by such components of the Department of Homeland Security as the Secretary of Homeland Security may direct, and, with respect to offenses over which the United States Postal Service has jurisdiction, by the Postal Service. Such authority of the Secretary of the Treasury, the Secretary of Homeland Security, and the Postal Service shall be exercised in accordance with an agreement which shall be entered into by the Secretary of the Treasury, the Secretary of Homeland Security, the Postal Service, and the Attorney General."],[0,"(f) As used in this section—"],[1,"(1) the term \"monetary transaction\" means the deposit, withdrawal, transfer, or exchange, in or affecting interstate or foreign commerce, of funds or a monetary instrument (as defined in section 1956(c)(5) of this title) by, through, or to a financial institution (as defined in section 1956 of this title), including any transaction that would be a financial transaction under section 1956(c)(4)(B) of this title, but such term does not include any transaction necessary to preserve a person's right to representation as guaranteed by the sixth amendment to the Constitution;"],[1,"(2) the term \"criminally derived property\" means any property constituting, or derived from, proceeds obtained from a criminal offense; and"],[1,"(3) the terms \"specified unlawful activity\" and \"proceeds\" shall have the meaning given those terms in section 1956 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1957?type=usc&year=mostrecent&link-type=html"},"head":"§1957. Engaging in monetary transactions in property derived from specified unlawful activity","tname":"Crimes and Criminal Procedure","by":{"2":"36, 36","3":"13, 13"}},{"t":"rule","label":"Fed. R. Evid. 301","url":"https://www.law.cornell.edu/rules/fre/rule_301","by":{"2":"37"}},{"t":"case","label":"Alwan v. Ashcroft","cite":"388 F.3d 507","y":2004,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/388/507/","by":{"3":"22"}},{"t":"case","label":"BedRoc Ltd., LLC v. United States","cite":"541 U.S. 176","y":2004,"id":"2003/02-1593","sc":1,"sum":"The Court ruled that because sand and gravel were not commercially valuable in 1919 when the Pittman Act was passed, they were not \"valuable minerals\" covered under the Act.","sumSrc":"Oyez","by":{"3":"17"}},{"t":"case","label":"Blenheim Cap. Holdings Ltd. v. Lockheed Martin Corp.","cite":"53 F.4th 286","y":2022,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/53/286/","by":{"3":"8"}},{"t":"case","label":"Cassirer v. Thyssen-Bornemisza Collection Found.","cite":"596 U.S. 107","y":2022,"id":"2021/20-1566","sc":1,"sum":"In a suit raising non-federal claims against a foreign state or instrumentality under the Foreign Sovereign Immunities Act of 1976, a court should determine the substantive law by using the same choice-of-law rule applicable in a similar suit against a private party.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"18"}},{"t":"case","label":"Cheng Fan Kwok v. Immigr. & Naturalization Serv.","cite":"392 U.S. 206","y":1968,"id":"1967/638","sc":1,"sum":"Jurisdietion to review the denial by a district dir(etor of immigration of a stlav of deportation, requested by a Chinese seaian'who had deserted his ship and remained unlawfully in this country, where the pertinent order was not entered in the course of a deportation proceeding conducted under §242 (b) of the Immigration and Nationality Act, is not, under the provisions of § 106 (a), vested exclusively in the …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"6"}},{"t":"case","label":"Fed. Republic of Germany v. Philipp","cite":"592 U.S. 169","y":2021,"url":"https://supreme.justia.com/cases/federal/us/592/169/","sc":1,"op":9,"by":{"3":"18"}},{"t":"case","label":"First Nat’l City Bank v. Banco Para el Comercio Exterior de Cuba","cite":"462 U.S. 611","y":1983,"id":"1982/81-984","sc":1,"op":1,"ar":6,"sum":"Under principles of equity common to international law and federal common law, petitioner may apply the claimed setoff, notwithstanding the fact that respondent was established as a separate juridical entity.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"18"}},{"t":"case","label":"Healy v. Ratta","cite":"292 U.S. 263","y":1934,"id":"scdb/1933-157","sc":1,"sum":"(1) That the matter in controversy did not embrace the right to restrain enforcement of the law by other officers in other places in the State, and that the collateral effect of the decree, by virtue of stare decisis, upon other and distinct controversies with other officers, could not be considered in ascertaining whether the jurisdictional amount was involved, even though their decision might turn on the same …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"6"}},{"t":"case","label":"Merrill Lynch, Pierce, Fenner & Smith Inc. v. Manning","cite":"578 U.S. 374","y":2016,"id":"2015/14-1132","sc":1,"sum":"The Court determined that the Securities Exchange Act of 1934 creates the same test for establishing federal jurisdiction as the general test for whether a federal court has jurisdiction: Whether the case “arises under” federal law.","sumSrc":"Oyez","by":{"3":"6"}},{"t":"case","label":"Mertens v. Hewitt Assocs.","cite":"508 U.S. 248","y":1993,"id":"1992/91-1671","sc":1,"sum":"ERISA does not authorize suits for money damages against nonfiduciaries who knowingly participate in a fiduciary's breach of fiduciary duty. ERISA §502(a)(3) permits plan participants to bring civil actions to obtain \"appropriate equitable relief\" to redress violations of the statute or a plan. Assuming, arguendo,that this creates a cause of action against nonfiduciaries who knowingly assist in a fiduciary's breach …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"18"}},{"t":"case","label":"Montanile v. Bd. of Trs. of Nat’l Elevator Indus. Health Benefit Plan","cite":"577 U.S. 136","y":2016,"id":"2015/14-723","sc":1,"ar":1,"sum":"The Court determined that the Employee Retirement Income Security Act of 1974 does not allow for a suit to recover reimbursement of an asset that has been fully disbursed on non-traceable items such as services.","sumSrc":"Oyez","by":{"3":"15"}},{"t":"case","label":"Nat’l Mut. Ins. Co. of D.C. v. Tidewater Transfer Co.","cite":"337 U.S. 582","y":1949,"id":"scdb/1948-103","sc":1,"sum":"The Act is constitutional and the judgment is reversed. Pp. 583-585, 604. 165 F. 2d 531, revered. A District of Columbia corporation sued a Virginia corporation in the Federal District Court for Maryland, the jurisdiction depending solely on diversity of citizenship. The District Court dismissed the complaint. The Court of Appeals affirmed. 165 F. 2d 531. This Court granted certiorari. 333 U. S. 860. Reversed, p. …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"5"}},{"t":"case","label":"St. Louis & S.F.R. Co. v. Spiller","cite":"274 U.S. 304","y":1927,"id":"scdb/1926-125","sc":1,"ar":2,"sum":"1. Assuming that a shipper’s claim for moneys collected from him by a railroad through excessive charges might be entitled to preferentiai payment from receivers of the railroad, subsequently appointed, if the moneys were traced into th^ir hands,.they are not so traced by showing that, for years which elapsed between the time of the overcharges and the transfer of the railroad property from the receivership to, a …","sumSrc":"Headnote (U.S. Reports)","by":{"3":"15"}},{"t":"case","label":"United States v. $448,342.85","cite":"969 F.2d 474","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/969/474/","by":{"3":"15"}},{"t":"case","label":"United States v. Braxtonbrown-Smith","cite":"278 F.3d 1348","y":2002,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/278/1348/","by":{"3":"14"}},{"t":"case","label":"United States v. Dazey","cite":"403 F.3d 1147","y":2005,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/403/1147/","sum":"Noting that without fraudulent funds, defendant’s “account did not have sufficient funds to wire the $100,000”.","sumSrc":"brief:3","by":{"3":"13"}},{"t":"case","label":"United States v. Loe","cite":"248 F.3d 449","y":2001,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/248/449/","by":{"3":"14"}},{"t":"case","label":"United States v. Mooney","cite":"401 F.3d 940","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/401/940/","by":{"3":"13"}},{"t":"case","label":"United States v. Rutgard","cite":"116 F.3d 1270","y":1997,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/116/1270/","by":{"3":"13"}},{"t":"case","label":"United States v. Voigt","cite":"89 F.3d 1050","y":1996,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/89/1050/","by":{"3":"14"}},{"t":"usc","label":"18 U.S.C. § 982","url":"https://www.law.cornell.edu/uscode/text/18/982","subs":["(b)(1)"],"by":{"3":"14"}},{"t":"usc","label":"18 U.S.C. § 984","url":"https://www.law.cornell.edu/uscode/text/18/984","subs":["(a)"],"by":{"3":"14"}},{"t":"usc","label":"18 U.S.C. § 1956","url":"https://www.law.cornell.edu/uscode/text/18/1956","subs":["(a)"],"by":{"3":"14, 15"}},{"t":"usc","label":"21 U.S.C. § 853","url":"https://www.law.cornell.edu/uscode/text/21/853","subs":["(p)"],"stext":{"head":"§853. Criminal forfeitures","paras":[[0,"(a) Property subject to criminal forfeiture"],[0,"Any person convicted of a violation of this subchapter or subchapter II punishable by imprisonment for more than one year shall forfeit to the United States, irrespective of any provision of State law—"],[1,"(1) any property constituting, or derived from, any proceeds the person obtained, directly or indirectly, as the result of such violation;"],[1,"(2) any of the person's property used, or intended to be used, in any manner or part, to commit, or to facilitate the commission of, such violation; and"],[1,"(3) in the case of a person convicted of engaging in a continuing criminal enterprise in violation of section 848 of this title, the person shall forfeit, in addition to any property described in paragraph (1) or (2), any of his interest in, claims against, and property or contractual rights affording a source of control over, the continuing criminal enterprise."],[0,"The court, in imposing sentence on such person, shall order, in addition to any other sentence imposed pursuant to this subchapter or subchapter II, that the person forfeit to the United States all property described in this subsection. In lieu of a fine otherwise authorized by this part, a defendant who derives profits or other proceeds from an offense may be fined not more than twice the gross profits or other proceeds."],[0,"(b) Meaning of term \"property\""],[0,"Property subject to criminal forfeiture under this section includes—"],[1,"(1) real property, including things growing on, affixed to, and found in land; and"],[1,"(2) tangible and intangible personal property, including rights, privileges, interests, claims, and securities."],[0,"(c) Third party transfers"],[0,"All right, title, and interest in property described in subsection (a) vests in the United States upon the commission of the act giving rise to forfeiture under this section. Any such property that is subsequently transferred to a person other than the defendant may be the subject of a special verdict of forfeiture and thereafter shall be ordered forfeited to the United States, unless the transferee establishes in a hearing pursuant to subsection (n) that he is a bona fide purchaser for value of such property who at the time of purchase was reasonably without cause to believe that the property was subject to forfeiture under this section."],[0,"(d) Rebuttable presumption"],[0,"There is a rebuttable presumption at trial that any property of a person convicted of a felony under this subchapter or subchapter II is subject to forfeiture under this section if the United States establishes by a preponderance of the evidence that—"],[1,"(1) such property was acquired by such person during the period of the violation of this subchapter or subchapter II or within a reasonable time after such period; and"],[1,"(2) there was no likely source for such property other than the violation of this subchapter or subchapter II."],[0,"(e) Protective orders"],[0,"(1) Upon application of the United States, the court may enter a restraining order or injunction, require the execution of a satisfactory performance bond, or take any other action to preserve the availability of property described in subsection (a) for forfeiture under this section—"],[1,"(A) upon the filing of an indictment or information charging a violation of this subchapter or subchapter II for which criminal forfeiture may be ordered under this section and alleging that the property with respect to which the order is sought would, in the event of conviction, be subject to forfeiture under this section; or"],[1,"(B) prior to the filing of such an indictment or information, if, after notice to persons appearing to have an interest in the property and opportunity for a hearing, the court determines that—"],[2,"(i) there is a substantial probability that the United States will prevail on the issue of forfeiture and that failure to enter the order will result in the property being destroyed, removed from the jurisdiction of the court, or otherwise made unavailable for forfeiture; and"],[2,"(ii) the need to preserve the availability of the property through the entry of the requested order outweighs the hardship on any party against whom the order is to be entered:"],[0,"Provided, however, That an order entered pursuant to subparagraph (B) shall be effective for not more than ninety days, unless extended by the court for good cause shown or unless an indictment or information described in subparagraph (A) has been filed."],[0,"(2) A temporary restraining order under this subsection may be entered upon application of the United States without notice or opportunity for a hearing when an information or indictment has not yet been filed with respect to the property, if the United States demonstrates that there is probable cause to believe that the property with respect to which the order is sought would, in the event of conviction, be subject to forfeiture under this section and that provision of notice will jeopardize the availability of the property for forfeiture. Such a temporary order shall expire not more than fourteen days after the date on which it is entered, unless extended for good cause shown or unless the party against whom it is entered consents to an extension for a longer period. A hearing requested concerning an order entered under this paragraph shall be held at the earliest possible time and prior to the expiration of the temporary order."],[0,"(3) The court may receive and consider, at a hearing held pursuant to this subsection, evidence and information that would be inadmissible under the Federal Rules of Evidence."],[0,"(4) Order to repatriate and deposit.—"],[1,"(A) In general.—Pursuant to its authority to enter a pretrial restraining order under this section, the court may order a defendant to repatriate any property that may be seized and forfeited, and to deposit that property pending trial in the registry of the court, or with the United States Marshals Service or the Secretary of the Treasury, in an interest-bearing account, if appropriate."],[1,"(B) Failure to comply.—Failure to comply with an order under this subsection, or an order to repatriate property under subsection (p), shall be punishable as a civil or criminal contempt of court, and may also result in an enhancement of the sentence of the defendant under the obstruction of justice provision of the Federal Sentencing Guidelines."],[0,"(f) Warrant of seizure"],[0,"The Government may request the issuance of a warrant authorizing the seizure of property subject to forfeiture under this section in the same manner as provided for a search warrant. If the court determines that there is probable cause to believe that the property to be seized would, in the event of conviction, be subject to forfeiture and that an order under subsection (e) may not be sufficient to assure the availability of the property for forfeiture, the court shall issue a warrant authorizing the seizure of such property."],[0,"(g) Execution"],[0,"Upon entry of an order of forfeiture under this section, the court shall authorize the Attorney General to seize all property ordered forfeited upon such terms and conditions as the court shall deem proper. Following entry of an order declaring the property forfeited, the court may, upon application of the United States, enter such appropriate restraining orders or injunctions, require the execution of satisfactory performance bonds, appoint receivers, conservators, appraisers, accountants, or trustees, or take any other action to protect the interest of the United States in the property ordered forfeited. Any income accruing to or derived from property ordered forfeited under this section may be used to offset ordinary and necessary expenses to the property which are required by law, or which are necessary to protect the interests of the United States or third parties."],[0,"(h) Disposition of property"],[0,"Following the seizure of property ordered forfeited under this section, the Attorney General shall direct the disposition of the property by sale or any other commercially feasible means, making due provision for the rights of any innocent persons. Any property right or interest not exercisable by, or transferable for value to, the United States shall expire and shall not revert to the defendant, nor shall the defendant or any person acting in concert with him or on his behalf be eligible to purchase forfeited property at any sale held by the United States. Upon application of a person, other than the defendant or a person acting in concert with him or on his behalf, the court may restrain or stay the sale or disposition of the property pending the conclusion of any appeal of the criminal case giving rise to the forfeiture, if the applicant demonstrates that proceeding with the sale or disposition of the property will result in irreparable injury, harm, or loss to him."],[0,"(i) Authority of the Attorney General"],[0,"With respect to property ordered forfeited under this section, the Attorney General is authorized to—"],[1,"(1) grant petitions for mitigation or remission of forfeiture, restore forfeited property to victims of a violation of this subchapter, or take any other action to protect the rights of innocent persons which is in the interest of justice and which is not inconsistent with the provisions of this section;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/853?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§853. Criminal forfeitures","tname":"Food and Drugs","by":{"3":"14"}},{"t":"usc","label":"28 U.S.C. § 1332","url":"https://www.law.cornell.edu/uscode/text/28/1332","by":{"3":"19"}}]};